def solve_axis_aligned(n, m, matrix):
    """Count axis-aligned squares (sides parallel to matrix sides)."""
    count = 0

    for r in range(n):
        for c in range(m):
            size = 2
            while True:
                # Check if we can have a square of current size with top-left at (r, c)
                # Square occupies rows r to r+size-1, columns c to c+size-1

                if r + size > n or c + size > m:
                    break

                square_valid = True

                # Check all border cells are 1
                for i in range(size):
                    if not is_1(matrix, r + i, c):  # top side
                        square_valid = False
                    if not is_1(matrix, r, c + i):   # left side
                        square_valid = False
                    if not is_1(matrix, r + size - 1, c + i):  # bottom side
                        square_valid = False
                    if not is_1(matrix, r + i, c + size - 1):  # right side
                        square_valid = False

                if not square_valid:
                    break

                # Check no foreign 1 touches this square (including diagonals)
                # Check rectangle one cell outside the square
                for i in range(-1, size):
