    # (cr, cc) -> (cr+r, cc) -> (cr, cc+(r-1)) -> ... forming a diamond
    # Actually a diamond with side length k (in Manhattan distance terms)
    # For a diamond of size k, it goes k cells in each direction

    for cr in range(n):
        for cc in range(m):
            size = 2
            while True:
                # Diamond of size 'size' where size represents the "radius"
                # The diamond extends size cells in each direction from center
