        d = 2
        while d * d <= num:
            if num % d == 0:
                count = 0
                while num % d == 0:
                    count += 1
                    num //= d
                if d not in prime_counts:
                    prime_counts[d] = [0] * n
                prime_counts[d][i] = count
            d += 1
        if num > 1:
            if num not in prime_counts:
                prime_counts[num] = [0] * n
            prime_counts[num][i] += 1

    def dinic_max_flow(n_nodes, source, sink, adj):
        level = [0] * n_nodes
        ptr = [0] * n_nodes

        def bfs():
            nonlocal level
            level = [-1] * n_nodes
            level[source] = 0
            queue = deque([source])
            while queue:
                u = queue.popleft()
                for v, cap, rev in adj[u]:
                    if cap > 0 and level[v] == -1:
                        level[v] = level[u] + 1
                        queue.append(v)
            return level[sink] != -1

        def dfs(u, pushed):
            if pushed == 0 or u == sink:
                return pushed
            for i in range(ptr[u], len(adj[u])):
                ptr[u] = i
                v, cap, rev = adj[u][i]
                if cap > 0 and level[v] == level[u] + 1:
                    tr = dfs(v, min(pushed, cap))
                    if tr > 0:
                        adj[u][i][1] -= tr
                        adj[v][rev][1] += tr
                        return tr
            return 0

        flow = 0
        while bfs():
            ptr = [0] * n_nodes
            while True:
                tr = dfs(source, float('inf'))
                if tr == 0:
                    break
                flow += tr
        return flow

    total = 0

    for p, counts in prime_counts.items():
        # Build bipartite graph: odd 1-indexed -> source, even 1-indexed -> sink
        # In 0-indexed: even positions, odd positions
        source = 2 * n
        sink = 2 * n + 1
        num_nodes = sink + 1

        adj = [[] for _ in range(num_nodes)]

        def add_edge(u, v, cap):
            adj[u].append([v, cap, len(adj[v])])
            adj[v].append([u, 0, len(adj[u]) - 1])  # reverse with 0 capacity

        # Source connects to odd 1-indexed (0, 2, 4... in 0-indexed)
        for i in range(n):
            if (i + 1) % 2 == 1 and counts[i] > 0:
                add_edge(source, i, counts[i])

        # Even 1-indexed (1, 3, 5... in 0-indexed) connects to sink
        for i in range(n):
            if (i + 1) % 2 == 0 and counts[i] > 0:
                add_edge(i, sink, counts[i])

        # Good pairs: connect between different parities
        for u, v in pairs:
            add_edge(u, v, float('inf'))
            add_edge(v, u, float('inf'))

        total += dinic_max_flow(num_nodes, source, sink, adj)

    return str(total) + '\n'

