    result = [0] * n

    # Check up to 300 for the largest possible a_i
    for i in range(n):
        best = None
        best_score = float('inf')

        for candidate in range(1, 301):
            cand_factors = get_all_factors(candidate)

            # Check if any factor conflicts with previously assigned numbers
            conflicts = False
            for j in range(i):
                if cand_factors & used_primes[j]:
                    conflicts = True
                    break

            if not conflicts:
                # Calculate score: sum of gcd(a[i], b[i]) for all assignments
                score = sum(gcd(a[k], result[k]) for k in range(i + 1))
