def solve_brute():
    """Geometric solution"""

    def cross(o, a, b):
        return (a[0] - o[0]) * (b[1] - o[1]) - (a[1] - o[1]) * (b[0] - o[0])

    def point_inside_or_boundary(p, a, b, c):
        """Check if p is inside or on boundary of triangle abc, assuming valid triangle (no collinear)"""
        d1 = cross(a, b, p)
        d2 = cross(b, c, p)
        d3 = cross(c, a, p)

