                for c_out in range(max(0, n_p + 10*c_in - 9*k), min(10*c_in, 9*k)):
                    S = n_p + 10*c_in - c_out
                    # S can spread across k positions, but we need to ensure average is at most 9
                    if S <= k * 9:
                        contribution = S * F[p] + c_out * F[p+1]
                        new_dp[c_out] = max(new_dp.get(c_out, -1), val + contribution)
            dp = new_dp

        result = max(dp.values()) if dp else 0
        results.append(result)

    return '\n'.join(map(str, results))

