import math

def solution(input_str):
    parts = input_str.strip().split()
    l, r = int(parts[0]), int(parts[1])

    # Ensure l <= r
    if l > r:
        l, r = r, l

    # If range is invalid or all numbers < 2 (not prime)
    if l >= 1 and r < 2:
        return '0'

    # Sieve size and initialize
    n = r - l + 1
    sieve = [True] * n

    # 0 and 1 are not prime (by definition and don't satisfy p % 4 == 1 condition)
    if l < 2:
        sieve[0] = False  # corresponds to 1
        if n > 1:
            sieve[1] = False  # corresponds to 2 (but 2 should be prime - fix below)

    # Mark 1 and handle edge case for 2
    sieve[0] = False  # number < 2 is never prime
    if l == 1 and n > 0:
        # sieve[0] = 1, which is not prime
        pass
    if l == 2 and n > 0:
        # sieve[0] = 2, which IS prime, should stay True
        pass

    # Set sieve[0] if number < 2
    if l < 2:
        sieve[0] = False

    # Precompute primes up to sqrt(r)
    sqrt_r = int(math.isqrt(r))

    if sqrt_r >= 2:
        limit = max(sqrt_r, 2)
        is_prime_small = [True] * (limit + 1)
        is_prime_small[0] = is_prime_small[1] = False
        for i in range(2, int(math.isqrt(limit)) + 1):
            if is_prime_small[i]:
                for j in range(i*i, limit + 1, i):
                    is_prime_small[j] = False
        small_primes = [i for i in range(2, limit + 1) if is_prime_small[i]]

    # Mark composites in [l, r]
    for p in small_primes:
        if p * p > r:
            break

        # First multiple of p >= l, but at least p*p
        start = max(p * p, ((l + p - 1) // p) * p)
        idx = start - l

        if idx < n:
            for i in range(idx, n, p):
                sieve[i] = False

    # Count primes that are either 2 or ≡ 1 (mod 4)
    count = 0
    for i in range(n):
        if sieve[i]:
            num = l + i
            if num == 2 or num % 4 == 1:
                count += 1

    return str(count)

