MOD = 10**9 + 7

def solution(s):
    s = s.strip()
    n = len(s)
    pos = 0

    def parse_number():
        nonlocal pos
        start = pos
        while pos < n and s[pos].isdigit():
            pos += 1
        if start == pos:
            raise ValueError("Expected number")
        return int(s[start:pos])

    def parse_range(l, r):
        """Concatenate numbers from l to r"""
        result = []
        for i in range(l, r + 1):
            result.append(str(i))
        return int("".join(result))

    def parse_term():
        nonlocal pos
        num1 = parse_number()

        if pos < n and s[pos] == '-':
            pos += 1
            num2 = parse_number()
            return parse_range(num1, num2)
        elif pos < n and s[pos] == '(':
            pos += 1  # consume '('
            expr_result = parse_expression()
            if pos < n and s[pos] == ')':
                pos += 1  # consume ')'
            # Repeat expr_result, num1 times
            expr_str = str(expr_result)
            result_str = []
            for _ in range(num1):
                result_str.append(expr_str)
            return int("".join(result_str)) % MOD
        else:
            return num1

    def parse_expression():
        nonlocal pos
        result = parse_term()

        while pos < n and s[pos] == '+':
            pos += 1  # consume '+'
            term_result = parse_term()
            result = concatenate(result, term_result)

        return result

    def concatenate(a, b):
        """Concatenate a and b: a * 10^len(b) + b"""
        b_str = str(b)
        b_len = len(b_str)
        return (a * pow(10, b_len, MOD) + b) % MOD

    result = parse_expression()
    return str(result)

def solution(input_string):
    lines = input_string.strip().split('\n')
    if not lines:
        return ""

    t = int(lines[0])
    results = []

    for i in range(1, t + 1):
        if i < len(lines) and lines[i].strip():
            n, k = map(int, lines[i].split())

            seen = set()
            total_len = 0
            found = False

            while not found:
                # Get k smallest unused positive integers
                items = []
                cand = 1
                while len(items) < k:
                    if cand not in seen:
                        items.append(cand)
                        seen.add(cand)
                    cand += 1

                s = sum(items)
                seen.add(s)

                # Check if n is in the k regular numbers
                for idx in range(k):
                    if items[idx] == n:
                        results.append(str(total_len + idx + 1))
                        found = True
                        break

                # Check if n is the sum
                if not found and s == n:
                    results.append(str(total_len + k + 1))
                    found = True

                total_len += k + 1

    return '\n'.join(results)
